def test_yields_each_nonempty_page():
    pages = [['a', 'b'], ['c'], []]

    def fetch_page():
        return pages.pop(0)

    paginator = Paginator(fetch_page)
    assert next(paginator) == ['a', 'b'], 'the first call must return the first non-empty page'
    assert next(paginator) == ['c'], 'the second call must return the second non-empty page'

def test_stops_on_empty_page():
    pages = [['x'], []]

    def fetch_page():
        return pages.pop(0)

    paginator = Paginator(fetch_page)
    next(paginator)
    try:
        next(paginator)
        assert False, 'an empty page from fetch_page must raise StopIteration'
    except StopIteration:
        pass

def test_works_in_a_for_loop():
    pages = [['a'], ['b'], []]

    def fetch_page():
        return pages.pop(0)

    collected = [page for page in Paginator(fetch_page)]
    assert collected == [['a'], ['b']], 'a for-loop over the paginator must collect pages until StopIteration'

canonical:
class Paginator:
    def __init__(self, fetch_page):
        self.fetch_page = fetch_page

    def __iter__(self):
        return self

    def __next__(self):
        page = self.fetch_page()
        if not page:
            raise StopIteration
        return page
